property.value:
//(ClassDeclaration | RecordDeclaration | EnumDeclaration)[
  parent::ClassBody or parent::RecordBody or parent::EnumBody
][
  pmd-java:modifiers() = 'private'
][
  let $decl := .,
      $name := @SimpleName
  return not(
    ancestor::CompilationUnit[1]//*[
      (self::ClassType[@SimpleName = $name]
       or self::AmbiguousName[@Name = $name]
       or self::VariableAccess[@Name = $name])
      and not(ancestor::*[. is $decl])
    ]
  )
]

//MethodCall[
  (@MethodName = 'equals' or @MethodName = 'equalsIgnoreCase')
  and StringLiteral
]

//MethodCall[
  (@MethodName = 'equals' or @MethodName = 'equalsIgnoreCase')
  and ArgumentList/*[
    self::StringLiteral or self::InfixExpression[descendant::StringLiteral]
  ]
  and (pmd-java:matchesSig('java.lang.String#equals(java.lang.Object)')
       or pmd-java:matchesSig('java.lang.String#equalsIgnoreCase(java.lang.String)'))
]

//MethodCall[
  (@MethodName = 'startsWith' or @MethodName = 'endsWith')
  and (pmd-java:matchesSig('java.lang.String#startsWith(java.lang.String)')
       or pmd-java:matchesSig('java.lang.String#endsWith(java.lang.String)'))
]

//MethodCall[
  pmd-java:matchesSig('java.lang.String#contains(java.lang.CharSequence)')
]

//MethodCall[
  pmd-java:matchesSig('java.lang.String#isBlank()')
]

//InfixExpression[
  (
    @Operator = '||'
    and MethodCall[
      pmd-java:matchesSig('java.lang.String#isEmpty()')
    ]/VariableAccess/@Name
      = InfixExpression[@Operator = '==' and NullLiteral]/VariableAccess/@Name
  ) or (
    @Operator = '&&'
    and UnaryExpression[@Operator = '!']/MethodCall[
      pmd-java:matchesSig('java.lang.String#isEmpty()')
    ]/VariableAccess/@Name
      = InfixExpression[@Operator = '!=' and NullLiteral]/VariableAccess/@Name
  )
]

//MethodCall[
  pmd-java:matchesSig('java.util.List#get(int)')
  and ArgumentList/NumericLiteral[@ValueAsInt = 0]
]

//MethodCall[
  pmd-java:matchesSig('java.util.List#get(int)')
  and ArgumentList/InfixExpression[
    @Operator = '-'
    and NumericLiteral[@ValueAsInt = 1]
    and MethodCall[pmd-java:matchesSig('java.util.List#size()')]
  ]
]

//InfixExpression[
  (
    (@Operator = ('==', '!=', '>', '<='))
    and MethodCall[
      pmd-java:matchesSig('com.fasterxml.jackson.databind.JsonNode#size()')
    ]
    and NumericLiteral[@ValueAsInt = 0]
  ) or (
    (@Operator = ('==', '!=', '<', '>='))
    and NumericLiteral[@ValueAsInt = 0]
      [following-sibling::MethodCall[
        pmd-java:matchesSig('com.fasterxml.jackson.databind.JsonNode#size()')
      ]]
  )
]

//MethodCall[
  (@MethodName = 'toLowerCase' or @MethodName = 'toUpperCase')
  and (pmd-java:matchesSig('java.lang.String#toLowerCase()')
       or pmd-java:matchesSig('java.lang.String#toUpperCase()'))
]

//InfixExpression[
  (
    @Operator = ('==', '!=', '>', '<=')
    and MethodCall[
      @MethodName = 'length'
      and *[1][
        pmd-java:typeIs('java.lang.CharSequence')
        or pmd-java:typeIs('java.lang.String')
        or pmd-java:typeIs('java.lang.StringBuilder')
        or pmd-java:typeIs('java.lang.StringBuffer')
      ]
      and following-sibling::NumericLiteral[@ValueAsInt = 0]
    ]
  ) or (
    @Operator = ('==', '!=', '<', '>=')
    and NumericLiteral[@ValueAsInt = 0]
      [following-sibling::MethodCall[
        @MethodName = 'length'
        and *[1][
          pmd-java:typeIs('java.lang.CharSequence')
          or pmd-java:typeIs('java.lang.String')
          or pmd-java:typeIs('java.lang.StringBuilder')
          or pmd-java:typeIs('java.lang.StringBuffer')
        ]
      ]]
  )
]

//ConditionalExpression[
  *[1][
    pmd-java:typeIs('boolean')
    or pmd-java:typeIs('java.lang.Boolean')
  ]
  and *[2][self::StringLiteral[@Image = '"true"']]
  and *[3][self::StringLiteral[@Image = '"false"']]
]

//MethodCall[
  parent::ExpressionStatement
  and (@MethodName = 'setExecutable'
       or @MethodName = 'setReadable'
       or @MethodName = 'setWritable')
]

//MethodCall[
  @MethodName = 'printStackTrace'
  and ArgumentList[count(*) = 0]
]

//FieldAccess[
  @Name = ('out', 'err')
][pmd-java:typeIs('java.io.PrintStream')]

//Annotation[
  pmd-java:typeIs('com.claudecode.core.annotation.Explanation')
  and .//StringLiteral[string-length(@Image) < 22]
]

//LambdaExpression[
  LambdaParameterList[count(LambdaParameter) = 1]
  and MethodCall[
    TypeExpression
    and ArgumentList[count(*) = 1]
    and ArgumentList/VariableAccess/@Name
        = ancestor::LambdaExpression[1]/LambdaParameterList/LambdaParameter/VariableId/@Name
  ]
]

//MethodCall[
  pmd-java:matchesSig('com.fasterxml.jackson.databind.JsonNode#fields()')
]

//MethodCall[
  @MethodName = 'getProperty'
  and (pmd-java:matchesSig('java.lang.System#getProperty(java.lang.String)')
       or pmd-java:matchesSig('java.lang.System#getProperty(java.lang.String,java.lang.String)'))
  and ArgumentList/*[1][self::StringLiteral and @Image = '"os.name"']
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration) and @SimpleName = 'Platform'])
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration)
    and (ends-with(@SimpleName, 'Test') or ends-with(@SimpleName, 'Tests')
         or ends-with(@SimpleName, 'Properties') or ends-with(@SimpleName, 'Smoke'))])
]

//MethodCall[
  @MethodName = 'getInstance'
  and pmd-java:matchesSig('java.security.MessageDigest#getInstance(java.lang.String)')
  and ArgumentList/*[1][self::StringLiteral and @Image = '"SHA-256"']
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration) and @SimpleName = 'HashUtils'])
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration)
    and (ends-with(@SimpleName, 'Test') or ends-with(@SimpleName, 'Tests')
         or ends-with(@SimpleName, 'Properties') or ends-with(@SimpleName, 'Smoke'))])
]

//MethodCall[
  @MethodName = 'map'
  and MethodCall[pmd-java:matchesSig('java.lang.ProcessHandle#of(long)')]
  and ArgumentList/MethodReference[@MethodName = 'isAlive']
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration) and @SimpleName = 'ProcessUtils'])
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration)
    and (ends-with(@SimpleName, 'Test') or ends-with(@SimpleName, 'Tests')
         or ends-with(@SimpleName, 'Properties') or ends-with(@SimpleName, 'Smoke'))])
]

//MethodCall[
  @MethodName = 'move'
  and ArgumentList//FieldAccess[@Name = 'ATOMIC_MOVE']
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration) and @SimpleName = 'FileUtils'])
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration)
    and (ends-with(@SimpleName, 'Test') or ends-with(@SimpleName, 'Tests')
         or ends-with(@SimpleName, 'Properties') or ends-with(@SimpleName, 'Smoke'))])
]

//MethodCall[
  @MethodName = 'toUpperCase'
  and pmd-java:matchesSig('java.lang.Character#toUpperCase(char)')
  and ArgumentList/MethodCall[
    @MethodName = 'charAt'
    and ArgumentList/NumericLiteral[@ValueAsInt = 0]
    and VariableAccess[
      let $v := @Name
      return ancestor::*[
        self::InfixExpression or self::ReturnStatement
        or self::VariableDeclarator or self::ExpressionStatement
      ][1]//MethodCall[
        @MethodName = 'substring'
        and VariableAccess/@Name = $v
        and ArgumentList[count(*) = 1 and NumericLiteral[@ValueAsInt = 1]]
      ]
    ]
  ]
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration) and @SimpleName = 'StringUtils'])
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration)
    and (ends-with(@SimpleName, 'Test') or ends-with(@SimpleName, 'Tests')
         or ends-with(@SimpleName, 'Properties') or ends-with(@SimpleName, 'Smoke'))])
]

//Block[
  let $blk := .
  return LocalVariableDeclaration/VariableDeclarator[
    let $nl := VariableId/@Name,
        $src := MethodCall[
          @MethodName = 'indexOf'
          and ArgumentList[count(*) = 1 and CharLiteral[@Image = "'\n'"]]
        ]/VariableAccess/@Name
    return exists($src)
      and count($blk//MethodCall[@MethodName = 'substring' and VariableAccess/@Name = $src]) = 1
      and $blk//ConditionalExpression[
        ancestor::Block[1] is $blk
        and InfixExpression[VariableAccess/@Name = $nl]
        and .//MethodCall[
          @MethodName = 'substring'
          and VariableAccess/@Name = $src
          and ArgumentList[
            count(*) = 2
            and *[1][self::NumericLiteral and @ValueAsInt = 0]
            and *[2][self::VariableAccess and @Name = $nl]
          ]
        ]
      ]
  ]
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration) and @SimpleName = 'StringUtils'])
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration) and @SimpleName = 'FormatUtils'])
  and not(ancestor::*[(self::ClassDeclaration or self::RecordDeclaration or self::EnumDeclaration)
    and (ends-with(@SimpleName, 'Test') or ends-with(@SimpleName, 'Tests')
         or ends-with(@SimpleName, 'Properties') or ends-with(@SimpleName, 'Smoke'))])
]
